from jsonb_to_recordset($json$[{"id":"che-pe-111","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the triad lithium–sodium–potassium the atomic mass of sodium is close to","options":["the difference of the atomic masses of Li and K","the mean of the atomic masses of lithium and potassium","twice the atomic mass of potassium","the atomic number of lithium"],"answer_index":1,"explanation":"Li (7), Na (23) and K (39) illustrate Dobereiner's mean-mass rule for a triad.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-112","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Argon (atomic mass about 40) sits before potassium (about 39) in the older table because","options":["argon has the smaller atomic number, which Mendeleev already used","chemical properties forced the placement; atomic number later justified it","potassium is a noble gas","argon has fewer neutrons than potassium"],"answer_index":1,"explanation":"Mass inversion of the Ar–K pair is an anomalous pair of Mendeleev's table, resolved by Moseley's atomic-number order.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"historical-classification","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-113","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The modern periodic law states that properties of elements are a periodic function of their","options":["atomic masses","atomic numbers","mass numbers","neutron-to-proton ratios"],"answer_index":1,"explanation":"After Moseley, atomic number Z replaced atomic mass as the classifying index.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-114","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Henry Moseley's X-ray studies showed that the correct basis for classifying elements is","options":["atomic mass","atomic number","density","atomic volume"],"answer_index":1,"explanation":"The frequency of characteristic X-rays varies regularly with Z, not with A.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-115","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The long form of the periodic table is constructed primarily on the basis of","options":["atomic volumes of Lothar Meyer","electronic configurations of the elements","boiling points only","natural abundances"],"answer_index":1,"explanation":"Each period begins when a new principal shell starts to fill and ends at a noble-gas configuration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-116","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In the long form of the periodic table the number of vertical groups is","options":["seven","eight","sixteen","eighteen"],"answer_index":3,"explanation":"IUPAC numbers the groups from 1 to 18 in the 18-column table.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-117","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The long form of the periodic table contains how many horizontal periods?","options":["five","six","seven","eighteen"],"answer_index":2,"explanation":"Periods 1 to 7 run from hydrogen to the heaviest known elements.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-118","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A horizontal row of the periodic table is called a","options":["group","period","block","family of isotopes"],"answer_index":1,"explanation":"Elements in one period have the same valence principal quantum number.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-119","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A vertical column of the periodic table is called a","options":["period","group","series of isobars","shell"],"answer_index":1,"explanation":"A group collects elements with the same valence-shell configuration and similar chemistry.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-120","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Elements of one group show similar chemical properties mainly because they have","options":["the same mass number","the same valence-shell electronic configuration","identical atomic radii","the same number of neutrons"],"answer_index":1,"explanation":"Valence configuration repeats down a group (for example ns¹ for alkali metals).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"modern-law-table","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
